content.content:
{
  "id": "U1",
  "artifact_required": false,
  "goal": "数据与存储地基（三版第一块）：物件目录从编译期焊死的 14 件改为双源（内置清单 ＋ 用户物件），Item 带来源标记（builtin/user）、运行时宽高比、以及「原图 / 展示图」两个位（本期指向同一张）；修掉 persistence.ts 的 reconcileItems——它现在拿内置清单当基准 map，读回时会把不在清单上的用户物件直接丢弃；照片二进制（Blob）存 IndexedDB，状态树仍走 LocalStorage 但只存引用、不存图；存储 schema 升 v4，旧版数据照旧不迁移、作废重置、应用不崩；终结 saveState 的静默失败（现为空 catch）——写入失败必须能被上层捕获并冒泡，不再无声吞掉数据；工程可生产构建。",
  "criteria": [
    {
      "desc": "生产构建通过：Vite 生产构建成功、无类型错误。",
      "check": {
        "type": "command",
        "cmd": [
          "npm",
          "run",
          "build"
        ],
        "expect_exit": 0,
        "timeout_ms": 180000
      }
    },
    {
      "desc": "双源目录与 v4 持久化 e2e：注入一件用户物件，刷新后它仍在（不被 reconcileItems 丢弃）；内置 14 件仍对齐清单；预置 v3 旧数据启动不崩、按作废重置；图片二进制落在 IndexedDB，LocalStorage 里查不到图片二进制或 base64。",
      "check": {
        "type": "command",
        "cmd": [
          "npx",
          "playwright",
          "test",
          "e2e/u1-foundation.spec.ts",
          "--reporter=line"
        ],
        "expect_exit": 0,
        "timeout_ms": 180000
      }
    },
    {
      "desc": "静默失败终结 e2e：人为让存储写入失败（配额超限/隐私模式），错误能冒泡到上层并被界面感知，不出现「提示成功、刷新就没」的静默丢失。",
      "check": {
        "type": "command",
        "cmd": [
          "npx",
          "playwright",
          "test",
          "e2e/u1-storage-error.spec.ts",
          "--reporter=line"
        ],
        "expect_exit": 0,
        "timeout_ms": 180000
      }
    }
  ]
}

