373	  // tick 会话逐步提交的字段（叙述、下轮计划、决定、产出），合并进草稿
374	  'tick-field': {
375	    path: (seq) => PATHS.tickDraft(seq),
376	    mode: 'merge',
377	    validate(data) {
378	      mustObject(data, 'tick 字段');
379	      const allowed = ['narrative', 'next_plan', 'decisions', 'outputs', 'artifacts'];
380	      const keys = Object.keys(data);
381	      if (keys.length === 0) throw new Error('tick 字段至少要提交一项（narrative/next_plan/decisions/outputs/artifacts）');
382	      for (const k of keys) {
383	        if (!allowed.includes(k)) throw new Error(`tick 字段不认识 ${k}，只收 narrative/next_plan/decisions/outputs/artifacts`);
384	      }
385	      if ('narrative' in data) mustNonEmptyString(data.narrative, 'narrative（本轮叙述）');
386	      if ('next_plan' in data) mustNonEmptyString(data.next_plan, 'next_plan（下轮计划）');
