// tick-end 子命令：一轮 tick 的收尾三连——落 tick 正式档、渲染汇报（打印+存档）、放锁。
// 用法：tick-end --gen n --json '{"status":"ok"}'（status=本轮结局，映射退出码；
//      可选 action=本轮主动作，留档供 audit 还原）。
// 缺叙述/缺下轮计划/坏 status 都当场喊停且不放锁——锁留在原地就是「这轮没收好尾」的记号。
async function cmdTickEnd({ root, flags }) {
  if (flags.gen === undefined) {
    throw new CliError('tick-end 需要 --gen 报上 tick-begin 发的代数');
  }
  const generation = Number(flags.gen);
  if (typeof flags.gen !== 'string' || !Number.isInteger(generation)) {
    throw new CliError('--gen 需要带一个整数（tick-begin 发的代数）');
  }
  if (typeof flags.json !== 'string') {
    throw new CliError('tick-end 需要 --json 带上本轮结局，例如：--json \'{"status":"ok"}\'');
  }
  let data;
  try {
    data = JSON.parse(flags.json);
  } catch {
    throw new CliError('--json 的内容不是合法 JSON，请检查引号和括号');
  }
  if (typeof data !== 'object' || data === null || Array.isArray(data)) {
    throw new CliError('tick-end 的 --json 必须是一个 JSON 对象，例如：{"status":"ok"}');
  }

  // 复合收尾：--json 里顺带带上 tick 字段（narrative/next_plan/decisions/outputs）就先落草稿，
  // 等价于先 write tick-field 再收轮，一回合顶两回合；旧的分步写法（先 write tick-field 再 tick-end）照旧。
  // 走 write tick-field 的同一套校验（含叙述校验），坏字段进不了草稿——与分步写法一字不差。
  const FIELD_KEYS = ['narrative', 'next_plan', 'decisions', 'outputs'];
  const fields = {};
  for (const k of FIELD_KEYS) {
    if (k in data) fields[k] = data[k];
  }
  if (Object.keys(fields).length > 0) {
    WRITE_TYPES['tick-field'].validate(fields);
    if (typeof fields.narrative === 'string') {
      const check = checkNarrative(fields.narrative);
      if (!check.ok) {
        throw new CliError(`叙述不合格：${check.reason}`);
      }
    }
    // 草稿按轮次序号定位，序号从锁里现读（写类围栏已在分发处核过代数与锁，这里读到的必是本轮的锁）。
    const lock = await readLock(root);
    if (lock === null) {
      throw new CliError('锁已不存在，没法收尾——这轮多半已被接管或已经收过尾', EXIT.STALE_GENERATION);
    }
    const seq = lock.tick_seq;
    if (!Number.isInteger(seq) || seq <= 0) {
      throw new CliError('锁文件里的轮次序号不像话，没法把收尾字段落进草稿');
    }
    const rel = WRITE_TYPES['tick-field'].path(seq);
    const existing = (await readJson(root, rel)) ?? {};
    await writeJson(root, rel, { ...existing, ...fields }, { actor: '主控', event: 'write:tick-field' });
  }

  const result = await tickEnd(root, {
    generation,
    status: data.status,
    action: typeof data.action === 'string' ? data.action : null
  });
  process.stdout.write(result.markdown); // 汇报当场打印给触发者，最后一行照旧是 JSON 结果
  return {

